import re

from six.moves import collections_abc
from .provider import InfoModelDataProvider

from .query.executor import QueryExecutor
from .ims2.model import Ims2Validator, Ims2ChangeSetProvider
from .monitor import InfoModelChangeMonitor
from .results import InfoModelObject, ExtendedQueryResult, InfoModelChangeSet, InfoModelChangeSetsContainer


def check_connection_status(function):
    """Check connection status."""
    def _wrap(inst, *args, **kwargs):
        try:
            timeout = float(kwargs.get('timeout', args[-1]))
        except (IndexError, TypeError, ValueError):
            timeout = 0
        inst.provider.connection_monitor.wait_until_connected_to_infomodel(timeout)
        return function(inst, *args, **kwargs)
    return _wrap


class InfoModel(object):

    ims2_validator = Ims2Validator()

    def __init__(self,
                 address="192.168.255.129",
                 port=443,
                 username="Nemuadmin",
                 password="nemuuser",
                 use_ssl=True,
                 update_interval=1,
                 debug_log="admin_api.log",
                 bundle_path=None,
                 remote_host=None,
                 remote_host_username="ute",
                 remote_host_password="ute",
                 timeout=30,
                 queue_maxsize=0):
        self.provider = InfoModelDataProvider(
            address, port, username, password, use_ssl, update_interval, debug_log, bundle_path,
            remote_host, remote_host_username, remote_host_password, timeout, queue_maxsize=queue_maxsize)
        self.monitor = InfoModelChangeMonitor(queue_maxsize=queue_maxsize)
        self.provider.register_listener(self.monitor)

    def setup(self):
        """Setup InfoModel."""
        try:
            self.provider.setup()
        except Exception:
            self.provider.teardown()
            raise

    def teardown(self):
        """Teardown InfoModel. Release used resources."""
        self.provider.teardown()
        try:
            with self.monitor.event_queue.mutex:
                self.monitor.event_queue.queue.clear()
        except Exception:
            pass

    def reset(self):
        """Reset InfoModel."""
        self.provider.reset()

    def register_listener(self, listener):
        """Register InfoModel change listener."""
        self.provider.register_listener(listener)

    def unregister_listener(self, listener):
        """Unregister InfoModel change listener."""
        self.provider.unregister_listener(listener)

    def connect(self, timeout):
        """Connect to InfoModel."""
        try:
            self.provider.start(timeout)
        except Exception:
            self.provider.stop()
            raise

    def disconnect(self):
        """Disconnect from InfoModel."""
        self.provider.stop()

    def is_connected(self):
        """Check InfoModel connection status."""
        return self.provider.is_connected()

    def save_log(self, filename, timeout):
        """Save InfoModel log."""
        self.provider.save_log(filename, timeout)

    @check_connection_status
    def get_infomodel_dump(self, dist_name_regex, timeout):
        """Get InfoModel dump."""
        dist_name_filter = re.compile(dist_name_regex)
        return {dn: dump for dn, dump in self.monitor.get_infomodel_dump(timeout) if dist_name_filter.search(dn)}

    def get_infomodel_object(self, query, timeout):
        """Get InfoModel object."""
        return self.query_infomodel('get object {}'.format(query), extend_result=False, allow_negative_result=False, timeout=timeout)

    def check_infomodel_object(self, query, timeout):
        """Check if InfoModel object exists without failing a test."""
        return self.query_infomodel('check {}'.format(query), extend_result=False, allow_negative_result=True, timeout=timeout)

    @check_connection_status
    def query_infomodel(self, query, extend_result=False, allow_negative_result=False, timeout=None):
        """Query InfoModel."""
        query_result = QueryExecutor(self.monitor, allow_negative_result).execute(query, timeout)
        return self._wrap_query_result(query_result, extend_result)

    @check_connection_status
    def query_infomodel_sequence(self, queries, extend_result, timeout):
        """Query InfoModel sequence."""
        query_result = QueryExecutor(self.monitor).execute_sequence(queries, timeout)
        return [self._wrap_query_result(partial_result, extend_result) for partial_result in query_result]

    @check_connection_status
    def query_infomodel_parallel(self, queries, assertion_method, extend_result, timeout):
        """Query InfoModel parallel."""
        if assertion_method == 'any':
            query_result = QueryExecutor(self.monitor).execute_parallel_pass_if_any(queries, timeout)
        else:
            query_result = QueryExecutor(self.monitor).execute_parallel_pass_if_all(queries, timeout)

        if isinstance(query_result, list):
            return [self._wrap_query_result(partial_result, extend_result) for partial_result in query_result]
        return self._wrap_query_result(query_result, extend_result)

    @check_connection_status
    def query_infomodel_parallel_sequences(self, sequences, extend_result, timeout):
        """Query InfoModel parallel sequences."""
        query_result = QueryExecutor(self.monitor).execute_parallel_sequences(sequences, timeout)
        return [self._wrap_query_result(partial_result, extend_result) for partial_result in query_result]

    def _wrap_query_result(self, query_result, extend_result):
        if not isinstance(query_result, tuple):
            return query_result

        result, start_time, end_time, query_expression = query_result
        if isinstance(result, tuple):
            result = InfoModelObject(*result)
        elif isinstance(result, dict):
            result = InfoModelObject('', result)
        elif isinstance(result, collections_abc.Iterable):
            result = [InfoModelObject(*r) for r in result]

        return ExtendedQueryResult(result, start_time, end_time, query_expression) if extend_result else result

    def wait_for_response_after_reset(self, timeout_for_reset, timeout_for_response):
        """Wait for InfoModel response after reset"""
        if timeout_for_reset > 0.0:
            self.monitor.wait_for_reset(timeout_for_reset)
        self.monitor.wait_for_change(timeout_for_response)

    def wait_for_event(self, event, timeout):
        """Wait for InfoModel event."""
        return self.monitor.wait_for_event(event, timeout)

    @classmethod
    def initialize_ims2_validator(self, ims2_file_path):
        """Initialize IMS2 validator. Open IMS2 file for validation."""
        self.ims2_validator.initialize(ims2_file_path)

    @classmethod
    def add_expected_ims2_event(self, event):
        """Add expected InfoModel event for IMS2 validation."""
        self.ims2_validator.expect_event(event)

    @classmethod
    def add_expected_ims2_event_sequence(self, events):
        """Add expected InfoModel event squence for IMS2 validation."""
        self.ims2_validator.expect_event_sequence(events)

    @classmethod
    def validate_ims2(self):
        """Perform IMS2 validatotion. Keyword will check if all expected events occured in given InfoModel log."""
        return self.ims2_validator.validate()

    @staticmethod
    def get_change_sets(ims2_file_path, event):
        """Get change sets. Read IMS2 file and return change sets matching given event description."""
        result = Ims2ChangeSetProvider().get_change_sets(ims2_file_path, event)
        return [InfoModelChangeSet(changeset_dict) for changeset_dict in result]

    @staticmethod
    def get_multiple_change_sets(ims2_file_path, events):
        """Get change sets. Read IMS2 file and return change sets matching given event description."""
        result = Ims2ChangeSetProvider().get_multiple_change_sets(ims2_file_path, events)
        return InfoModelChangeSetsContainer(result)
